    "userdoc.addnode.td.disablevxlan": "<code>--disable-vxlan</code>",
    "userdoc.addnode.td.disablevxlandesc": "Disabilita la rete di overlay VXLAN su questo nodo.",
    "userdoc.addnode.td.hostname": "<code>--hostname &lt;nome&gt;</code>",
    "userdoc.addnode.td.hostnamedesc": "Sovrascrivere il nome host rilevato dalla macchina.",
