    "userdoc.addnode.td.installagentcmd": "<code>kctl --node &lt;IP&gt;:9091 installazione nodo --os-disk /dev/sda --join-controller &lt;host:port&gt; --dc-id DC1</code>",
    "userdoc.addnode.td.installctrl": "Installa (con controller)",
    "userdoc.addnode.td.installctrlcmd": "<code>kctl --node &lt;IP&gt;:9091 installazione nodo --os-disk /dev/sda --join-controller &lt;host:port&gt; --run-controller --dc-id DC1</code>",
    "userdoc.addnode.td.listdisks": "Elenca dischi / NIC",
    "userdoc.addnode.td.listdiskscmd": "<code>kctl --node &lt;IP&gt;:9091 dischi nodo</code>/<code>nics nodo</code>",
    "userdoc.addnode.td.listnodes": "Elenca / descrivi nodi",
    "userdoc.addnode.td.listnodescmd": "<code>kctl get nodes</code>/<code>kctl get node &lt;ID&gt;</code>",
    "userdoc.addnode.td.lvmvgname": "<code>--lvm-vg-name &lt;nome&gt;</code>",
    "userdoc.addnode.td.lvmvgnamedesc": "Nome del gruppo volumi LVM (solo con <code>--storage-backend lvm</code>).",
