    "userdoc.addnode.td.multictrlcmd": "<code>kctl -s &lt;IP1&gt;:9090 -s &lt;IP2&gt;:9090 get nodes</code>",
    "userdoc.addnode.td.nodeid": "<code>--node-id &lt;uuid&gt;</code>",
    "userdoc.addnode.td.nodeiddesc": "Imposta un UUID del nodo specifico invece di generarne uno automatico.",
