    "userdoc.kctlref.node.nics.cmd": "<code>nics</code>",
    "userdoc.kctlref.node.nics.desc": "Listar las interfaces de red de un nodo",
    "userdoc.kctlref.node.reject.cmd": "<code>reject</code>",
