    "fp.compare.iac": "Infrastruktur als Code",
    "fp.compare.ai": "KI-Integration",
    "fp.compare.isolation": "Vollständige Isolation des Betriebssystems",
    "fp.compare.legacy": "Unterstützung für Altanwendungen",
    "fp.compare.efficiency": "Ressourceneffizienz",
    "fp.compare.learning": "Lernkurve",
