    "userdoc.containers.spec.image.flag": "<code>--image</code>",
    "userdoc.containers.spec.network.desc": "コンテナを接続するブリッジ名",
    "userdoc.containers.spec.network.flag": "<code>--network</code>",
    "userdoc.containers.spec.port.desc": "<code>host:container</code> 形式のポートマッピング",
