    "userdoc.postgresql.h1": "PostgreSQL",
    "userdoc.postgresql.intro": "kcore NixOS postgresql package से node पर एक PostgreSQL database declare करता है। service kcoreOS पर ही चलता है। यह VM के अंदर नहीं चलता।",
    "userdoc.postgresql.note": "Version 1 node के Unix socket पर listen करता है। TCP enable नहीं है। node पर postgres superuser के रूप में connect करें: <code>sudo -u postgres psql -d app</code>।",
    "userdoc.postgresql.h2.declare": "Database declare करें",
    "userdoc.postgresql.declare.p": "पहला apply database बनाता है। बाद का apply port बदल सकता है। package, database name, या target node बदलना reject होता है।",
    "userdoc.postgresql.apply": "Apply: <code>kctl apply -f postgresql.yaml</code>। <code>kind: postgres</code> भी स्वीकार है।",
    "userdoc.postgresql.h2.commands": "Commands",
    "userdoc.postgresql.th.op": "Operation",
    "userdoc.postgresql.th.cmd": "Command",
    "userdoc.postgresql.cmd.apply": "Apply",
    "userdoc.postgresql.cmd.create": "Create",
    "userdoc.postgresql.cmd.get": "Get",
    "userdoc.postgresql.cmd.list": "List",
    "userdoc.postgresql.cmd.describe": "Describe",
    "userdoc.postgresql.cmd.delete": "Delete",
    "userdoc.postgresql.alias": "create, get, describe, और delete पर <code>postgres</code>, <code>postgresql</code> का alias है।",
    "userdoc.postgresql.h2.fields": "Fields",
    "userdoc.postgresql.th.field": "Field",
    "userdoc.postgresql.th.desc": "Description",
    "userdoc.postgresql.field.name": "Instance name। Letters, digits, hyphen, underscore, अधिकतम 63 characters, letter या digit से शुरू।",
    "userdoc.postgresql.field.database": "Database name। PostgreSQL identifier। जब name valid identifier हो तो default instance name। Immutable।",
    "userdoc.postgresql.field.package": "Nixpkgs attribute: <code>postgresql</code> (default), <code>postgresql_14</code>, <code>postgresql_15</code>, <code>postgresql_16</code>, या <code>postgresql_17</code>। Immutable।",
    "userdoc.postgresql.field.port": "service के लिए recorded port। Default 5432। Mutable। v1 में clients अभी भी local Unix socket उपयोग करते हैं।",
    "userdoc.postgresql.field.target": "Database host करने वाला node। Optional। controller ready node चुनता है जो पहले से PostgreSQL host नहीं करता। Immutable। CLI flag: <code>--target-node</code>।",
    "userdoc.postgresql.h2.upsert": "Re-apply",
    "userdoc.postgresql.upsert.p": "<code>kctl apply -f</code> और <code>kctl create postgresql</code> upsert करते हैं। Create और delete के लिए <code>vm-admin</code> चाहिए। Get और list read-only हैं।",
    "userdoc.postgresql.h2.connect": "Connect",
    "userdoc.postgresql.connect.p": "node NixOS config apply करने के बाद database उस node के Unix socket पर उपलब्ध है। resource delete करने से NixOS service definition हटती है और <code>/var/lib/postgresql</code> disk पर रहता है।",
    "userdoc.postgresql.h2.limits": "Current limits",
    "userdoc.postgresql.lim1": "प्रति node एक database। same node पर दूसरा instance reject होता है।",
    "userdoc.postgresql.lim2": "v1 में TCP listener और password setup नहीं। database तक node से पहुँचें।",
    "userdoc.postgresql.lim3": "package in-place नहीं बदल सकता। major upgrade के लिए delete और नया database चाहिए।",
    "userdoc.postgresql.lim4": "Multi-node PostgreSQL cluster Q1 2027 के लिए planned है। यह page single database cover करता है।",
    "userdoc.kctlref.create.postgresql.cmd": "<code>postgresql</code>",
    "userdoc.kctlref.create.postgresql.desc": "NixOS package से एक PostgreSQL database। Alias <code>postgres</code>। <a href=\"postgresql.html\">PostgreSQL</a> देखें।",
    "userdoc.kctlref.get.postgresql.cmd": "<code>postgresql</code>",
    "userdoc.kctlref.get.postgresql.alias": "<code>postgres</code>",
    "userdoc.kctlref.describe.postgresql.cmd": "<code>postgresql</code>",
    "userdoc.kctlref.describe.postgresql.alias": "<code>postgres</code>",
    "userdoc.kctlref.delete.postgresql.cmd": "<code>postgresql</code>",
    "userdoc.kctlref.delete.postgresql.desc": "NixOS service definition हटाएँ। <code>/var/lib/postgresql</code> disk पर रहता है। Alias <code>postgres</code>।",
    "userdoc.yaml.postgresql.h2": "PostgreSQL manifest (kind: Postgresql)",
    "userdoc.yaml.postgresql.p": "NixOS postgresql package से एक database, node पर VM में नहीं। Field reference: <a href=\"postgresql.html\">PostgreSQL</a>।",
    "userdoc.yaml.postgresql.apply": "Apply: <code>kctl apply -f postgresql.yaml</code>। <code>kind: postgres</code> भी स्वीकार है।",
    "userdoc.yaml.postgresql.kind": "Node पर एक PostgreSQL database",
